(function() {
    'use strict';

    class TechArenaAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'TechArena: Technology Company Multi-Market Competition';
            this.version = '1.1.0';

            this.ROUNDS = [
                {
                    briefing: 'Year 1: You lead a mid-sized technology company competing globally. Your portfolio includes gaming consoles, tablets, and smart home devices. Establish your market position by setting competitive prices, choosing your geographic focus, and allocating R&D between maintaining current products (incremental) and developing breakthrough innovations (disruptive). Five competitors are vying for dominance across Latin America, North America, and Europe.',
                    briefingEs: 'Periodo 1: Lideras una empresa tecnologica de tamano medio que compite globalmente. Tu portafolio incluye consolas de videojuegos, tablets y dispositivos inteligentes para el hogar. Establece tu posicion en el mercado fijando precios competitivos, eligiendo tu enfoque geografico y asignando I+D entre mantener productos actuales (incremental) y desarrollar innovaciones revolucionarias (disruptiva). Cinco competidores luchan por el dominio en America Latina, Norteamerica y Europa.',
                    competitiveShock: false,
                    shockMultiplier: 1.0
                },
                {
                    briefing: 'Year 2: COMPETITIVE SHOCK! A new Asian manufacturer has entered all three markets with aggressive pricing — 20% below current incumbents. Your market share is under pressure. You must decide: cut prices to compete, accelerate innovation to differentiate, shift distribution channels, or retreat from vulnerable segments. Your R&D pipeline from Year 1 is maturing. Brand equity and customer loyalty are now critical defenses.',
                    briefingEs: 'Periodo 2: SHOCK COMPETITIVO! Un nuevo fabricante asiatico ha ingresado a los tres mercados con precios agresivos — 20% por debajo de los competidores actuales. Tu participacion de mercado esta bajo presion. Debes decidir: reducir precios para competir, acelerar la innovacion para diferenciarte, cambiar canales de distribucion o retirarte de segmentos vulnerables. Tu pipeline de I+D del Periodo 1 esta madurando. La marca y la lealtad del cliente son ahora defensas criticas.',
                    competitiveShock: true,
                    shockMultiplier: 0.82
                },
                {
                    briefing: 'Year 3: The market is consolidating. The Asian competitor has captured significant value-segment share. This is your final year to maximize the Technology Market Value Index (TMVI). If your disruptive R&D investment has accumulated enough, a breakthrough product may launch, creating a new revenue stream. Final strategic moves: optimize pricing for lifecycle positioning, expand or consolidate geographic presence, and invest in brand building for long-term value.',
                    briefingEs: 'Periodo 3: El mercado se esta consolidando. El competidor asiatico ha capturado participacion significativa en el segmento de valor. Este es tu ultimo periodo para maximizar el Indice de Valor de Mercado Tecnologico (TMVI). Si tu inversion en I+D disruptiva ha acumulado suficiente, un producto revolucionario podria lanzarse, creando una nueva fuente de ingresos. Movimientos estrategicos finales: optimizar precios para posicionamiento de ciclo de vida, expandir o consolidar presencia geografica e invertir en marca para valor a largo plazo.',
                    competitiveShock: true,
                    shockMultiplier: 0.88
                }
            ];

            this.PRODUCTS = {
                console: { baseDemandUnits: 2.0, unitCost: 250, optimalPrice: 450, elasticity: 0.6, name: 'Gaming Console' },
                tablet:  { baseDemandUnits: 3.5, unitCost: 180, optimalPrice: 400, elasticity: 0.8, name: 'Tablet' },
                smartHome: { baseDemandUnits: 4.0, unitCost: 35, optimalPrice: 100, elasticity: 1.1, name: 'Smart Home' }
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 5000,
                    totalRevenue: 0,
                    grossMargin: 38.0,
                    marketShare: 20.0,
                    brandEquity: 50,
                    rdPipelineProgress: 0,
                    disruptiveLaunched: false,
                    marketsActive: 1,
                    cumulativeDisruptiveInvest: 0,
                    revenueHistory: [],
                    profitHistory: [],
                    marketShareHistory: [],
                    brandHistory: [],
                    marginHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    consolePrice: 499,
                    tabletPrice: 399,
                    smartHomePrice: 99,
                    rdIncremental: 70,
                    marketExpansion: 'one',
                    channelFocus: 'balanced'
                };
            }
            this._updateBriefing(state);
            this._setupRangeListener();

            var self = this;
            var sim = window.mySimulation;
            if (sim && sim.eventBus && typeof sim.eventBus.on === 'function' && !this._reactBound) {
                // FIX(v1.1.0): undo restores state but never re-invokes the view, and
                // language changes should re-render the (localized) briefing. Keep the
                // briefing reactive to both.
                this._reactBound = true;
                sim.eventBus.on('period:undone', function(st) { self._updateBriefing(st || sim.state); });
                sim.eventBus.on('language:changed', function() { self._updateBriefing(sim.state); });
            }
        }

        _setupRangeListener() {
            var slider = document.getElementById('rdIncrementalInput');
            var display = document.getElementById('rdValueDisplay');
            if (slider && display) {
                slider.addEventListener('input', function() {
                    display.textContent = slider.value + '%';
                });
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var briefEl = document.getElementById('briefingText');
            if (briefEl) {
                var lang = (window.mySimulation && window.mySimulation.currentLanguage) || 'en';
                briefEl.innerHTML = (lang === 'es' && round.briefingEs) ? round.briefingEs : round.briefing;
            }
        }

        validateDecisions(decisions) {
            // FIX(v1.1.0): removed a redundant _updateBriefing() here (it re-rendered
            // the briefing on every validate/preview). The next round is rendered by
            // calculateResults; the decision inputs are static and read below.
            var consoleInput = document.getElementById('consolePriceInput');
            if (consoleInput) decisions.consolePrice = parseFloat(consoleInput.value);

            var tabletInput = document.getElementById('tabletPriceInput');
            if (tabletInput) decisions.tabletPrice = parseFloat(tabletInput.value);

            var smartHomeInput = document.getElementById('smartHomePriceInput');
            if (smartHomeInput) decisions.smartHomePrice = parseFloat(smartHomeInput.value);

            var rdInput = document.getElementById('rdIncrementalInput');
            if (rdInput) decisions.rdIncremental = parseInt(rdInput.value);

            var marketInput = document.getElementById('marketExpansionInput');
            if (marketInput) decisions.marketExpansion = marketInput.value;

            var channelInput = document.getElementById('channelFocusInput');
            if (channelInput) decisions.channelFocus = channelInput.value;

            if (!decisions.consolePrice || decisions.consolePrice < 299 || decisions.consolePrice > 699) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('console_price_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.tabletPrice || decisions.tabletPrice < 249 || decisions.tabletPrice > 699) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('tablet_price_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.smartHomePrice || decisions.smartHomePrice < 49 || decisions.smartHomePrice > 199) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('smarthome_price_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var roundIdx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[roundIdx];

            var marketMultiplier = 1.0;
            if (d.marketExpansion === 'two') marketMultiplier = 2.2;
            if (d.marketExpansion === 'three') marketMultiplier = 3.5;

            var channelVolumeMultiplier = 1.0;
            var channelMarginEffect = 0;
            if (d.channelFocus === 'retail') { channelVolumeMultiplier = 1.15; channelMarginEffect = -3; }
            if (d.channelFocus === 'online') { channelVolumeMultiplier = 0.9; channelMarginEffect = 5; }
            if (d.channelFocus === 'enterprise') { channelVolumeMultiplier = 0.7; channelMarginEffect = 8; }
            if (d.channelFocus === 'balanced') { channelVolumeMultiplier = 1.0; channelMarginEffect = 0; }

            var incrementalBoost = 1 + (d.rdIncremental / 100) * 0.15;
            var disruptiveAlloc = (100 - d.rdIncremental) / 100;
            ds.cumulativeDisruptiveInvest += disruptiveAlloc * 800;

            var brandMultiplier = 0.7 + (ds.brandEquity / 100) * 0.6;

            var competitiveShockMult = round.shockMultiplier || 1.0;

            var totalRevenue = 0;
            var totalCOGS = 0;
            var productResults = {};

            var products = this.PRODUCTS;
            var priceMap = {
                console: d.consolePrice,
                tablet: d.tabletPrice,
                smartHome: d.smartHomePrice
            };

            var productKeys = ['console', 'tablet', 'smartHome'];
            for (var i = 0; i < productKeys.length; i++) {
                var key = productKeys[i];
                var prod = products[key];
                var price = priceMap[key];

                var priceRatio = prod.optimalPrice / price;
                var demandFactor = Math.pow(priceRatio, prod.elasticity);

                var units = prod.baseDemandUnits * demandFactor * marketMultiplier * channelVolumeMultiplier * brandMultiplier * incrementalBoost * competitiveShockMult;
                units = Math.round(units * 100) / 100;

                var revenue = units * price;
                var cogs = units * prod.unitCost;

                productResults[key] = { units: units, revenue: Math.round(revenue), cogs: Math.round(cogs) };
                totalRevenue += revenue;
                totalCOGS += cogs;
            }

            var rdBudget = 800;
            var marketingCost = 200 + (marketMultiplier > 2 ? 150 : (marketMultiplier > 1.5 ? 80 : 0));
            var operatingCosts = rdBudget + marketingCost + 300;

            var grossProfit = totalRevenue - totalCOGS;
            var grossMarginPct = totalRevenue > 0 ? (grossProfit / totalRevenue) * 100 : 0;
            grossMarginPct += channelMarginEffect;
            grossMarginPct = Math.max(10, Math.min(60, grossMarginPct));

            var netProfit = grossProfit - operatingCosts;

            var disruptiveRevenue = 0;
            if (ds.cumulativeDisruptiveInvest > 600 && state.currentPeriod >= 3 && !ds.disruptiveLaunched) {
                var successChance = Math.min(0.85, ds.cumulativeDisruptiveInvest / 1500);
                if (Math.random() < successChance) {
                    disruptiveRevenue = 800 + Math.round(Math.random() * 700);
                    ds.disruptiveLaunched = true;
                    totalRevenue += disruptiveRevenue;
                    netProfit += disruptiveRevenue * 0.45;
                }
            }

            totalRevenue = Math.round(totalRevenue);
            netProfit = Math.round(netProfit);

            var shareChange = 0;
            if (totalRevenue > 3000) shareChange += 3;
            else if (totalRevenue > 2000) shareChange += 1;
            else if (totalRevenue < 1000) shareChange -= 3;

            if (round.competitiveShock) shareChange -= 4;
            if (d.rdIncremental > 60) shareChange += 1;
            if (ds.brandEquity > 60) shareChange += 1;

            ds.marketShare = Math.max(5, Math.min(45, ds.marketShare + shareChange));

            var brandChange = 0;
            var avgPrice = (d.consolePrice + d.tabletPrice + d.smartHomePrice) / 3;
            if (avgPrice > 400) brandChange += 3;
            if (avgPrice > 500) brandChange += 2;
            if (avgPrice < 300) brandChange -= 4;
            if (d.rdIncremental > 50) brandChange += 1;
            if (round.competitiveShock && avgPrice < 350) brandChange -= 3;
            if (ds.disruptiveLaunched) brandChange += 8;
            ds.brandEquity = Math.max(10, Math.min(95, ds.brandEquity + brandChange));

            ds.cash += netProfit;
            ds.totalRevenue += totalRevenue;
            ds.grossMargin = Math.round(grossMarginPct * 10) / 10;
            ds.marketsActive = (d.marketExpansion === 'three') ? 3 : ((d.marketExpansion === 'two') ? 2 : 1);
            ds.rdPipelineProgress = Math.min(100, Math.round((ds.cumulativeDisruptiveInvest / 1500) * 100));

            ds.revenueHistory.push(totalRevenue);
            ds.profitHistory.push(netProfit);
            ds.marketShareHistory.push(ds.marketShare);
            ds.brandHistory.push(ds.brandEquity);
            ds.marginHistory.push(ds.grossMargin);

            // FIX(v1.1.0): advance the briefing synchronously. The previous setTimeout
            // closure read state.currentPeriod AFTER the framework had incremented it,
            // so it showed round N+2 (e.g. Year 2's briefing was skipped for Year 3's).
            // Guard on state identity so the deep-cloned competition preview never
            // mutates the live DOM.
            if (window.mySimulation && state === window.mySimulation.state) {
                var nextPeriod = (state.currentPeriod || 1) + 1;
                if (nextPeriod <= this.ROUNDS.length) {
                    this._updateBriefing({ currentPeriod: nextPeriod });
                }
            }

            return {
                period: state.currentPeriod,
                revenue: totalRevenue,
                cogs: Math.round(totalCOGS),
                grossProfit: Math.round(grossProfit),
                grossMargin: ds.grossMargin,
                operatingCosts: Math.round(operatingCosts),
                netProfit: netProfit,
                marketShare: ds.marketShare,
                brandEquity: ds.brandEquity,
                cash: ds.cash,
                marketsActive: ds.marketsActive,
                disruptiveRevenue: disruptiveRevenue,
                disruptiveLaunched: ds.disruptiveLaunched,
                rdPipeline: ds.rdPipelineProgress,
                consoleRevenue: productResults.console.revenue,
                tabletRevenue: productResults.tablet.revenue,
                smartHomeRevenue: productResults.smartHome.revenue
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('cashDisplay', 'domainState.cash',
                function(v) { return '$' + Math.round(v).toLocaleString() + 'M'; });
            uiManager.bind('revenueDisplay', 'results.revenue',
                function(v) { return '$' + Math.round(v).toLocaleString() + 'M'; });
            uiManager.bind('marginDisplay', 'domainState.grossMargin',
                function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('shareDisplay', 'domainState.marketShare',
                function(v) { return v.toFixed(1) + '%'; });
            uiManager.bind('brandDisplay', 'domainState.brandEquity');
            uiManager.bind('rdPipelineDisplay', 'domainState.rdPipelineProgress',
                function(v) { return v + '%'; });
        }

        getChartConfig() {
            return {
                financialChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Revenue (M$)',
                                data: [],
                                backgroundColor: 'rgba(102, 126, 234, 0.7)',
                                borderColor: '#667eea',
                                borderWidth: 2
                            },
                            {
                                label: 'Net Profit (M$)',
                                data: [],
                                backgroundColor: 'rgba(46, 204, 113, 0.7)',
                                borderColor: '#2ecc71',
                                borderWidth: 2
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Financial Performance', color: '#b0b0d0' },
                            legend: { labels: { color: '#b0b0d0' } }
                        },
                        scales: {
                            y: { beginAtZero: true, ticks: { color: '#8888aa' }, grid: { color: 'rgba(255,255,255,0.05)' } },
                            x: { ticks: { color: '#8888aa' }, grid: { color: 'rgba(255,255,255,0.05)' } }
                        }
                    }
                },
                marketChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: 'Market Share (%)',
                                data: [],
                                borderColor: '#9b59b6',
                                backgroundColor: 'rgba(155, 89, 182, 0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.3,
                                yAxisID: 'y'
                            },
                            {
                                label: 'Brand Equity',
                                data: [],
                                borderColor: '#e74c3c',
                                backgroundColor: 'rgba(231, 76, 60, 0.1)',
                                borderWidth: 3,
                                fill: true,
                                tension: 0.3,
                                yAxisID: 'y1'
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Market Position', color: '#b0b0d0' },
                            legend: { labels: { color: '#b0b0d0' } }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 50, position: 'left', ticks: { color: '#9b59b6' }, grid: { color: 'rgba(255,255,255,0.05)' }, title: { display: true, text: 'Market Share (%)', color: '#9b59b6' } },
                            y1: { beginAtZero: true, max: 100, position: 'right', ticks: { color: '#e74c3c' }, grid: { drawOnChartArea: false }, title: { display: true, text: 'Brand Equity', color: '#e74c3c' } },
                            x: { ticks: { color: '#8888aa' }, grid: { color: 'rgba(255,255,255,0.05)' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.revenueHistory.map(function(_, i) { return 'Y' + (i + 1); });
            return {
                financialChart: {
