        getPerformanceSummary(history) {
            if (!history.length) return {};

            var revenues = history.map(function(r) { return r.results ? r.results.revenue || 0 : 0; });
            var profits = history.map(function(r) { return r.results ? r.results.netProfit || 0 : 0; });
            var totalRevenue = revenues.reduce(function(s, v) { return s + v; }, 0);
            var totalProfit = profits.reduce(function(s, v) { return s + v; }, 0);
            var avgMargin = history.reduce(function(s, r) { return s + (r.results ? r.results.grossMargin || 0 : 0); }, 0) / history.length;

            var lastRecord = history[history.length - 1];
            var finalShare = lastRecord && lastRecord.results ? lastRecord.results.marketShare || 20 : 20;
            var finalBrand = lastRecord && lastRecord.results ? lastRecord.results.brandEquity || 50 : 50;
            var disruptiveLaunched = lastRecord && lastRecord.results ? lastRecord.results.disruptiveLaunched || false : false;

            var revenueGrowth = revenues.length > 1 ? ((revenues[revenues.length - 1] - revenues[0]) / Math.max(revenues[0], 1)) * 100 : 0;

            var tmvi = 0;
            tmvi += Math.min(25, (revenueGrowth / 15) * 25);
            tmvi += Math.min(20, (avgMargin / 35) * 20);
            tmvi += Math.min(20, (finalShare / 30) * 20);
            tmvi += Math.min(15, totalProfit > 0 ? Math.min(15, (totalProfit / 3000) * 15) : 0);
            tmvi += Math.min(10, (finalBrand / 80) * 10);
            tmvi += disruptiveLaunched ? 10 : Math.min(5, 0);

            if (disruptiveLaunched) tmvi += 15;
            if (avgMargin < 33) tmvi -= 10;

            tmvi = Math.max(0, Math.min(100, Math.round(tmvi)));

            var performance = 'Needs Improvement';
            if (tmvi >= 80) performance = 'Outstanding Technology Leader';
            else if (tmvi >= 65) performance = 'Strong Competitor';
            else if (tmvi >= 50) performance = 'Average Performer';
            else if (tmvi >= 35) performance = 'Below Expectations';

            var insights = [];
            if (revenueGrowth > 20) insights.push('Excellent revenue growth across markets.');
            if (revenueGrowth < 0) insights.push('Revenue declined over the simulation period. Pricing or market strategy needs rethinking.');
            if (avgMargin > 40) insights.push('Strong margin management demonstrates premium positioning.');
            if (avgMargin < 30) insights.push('Margin compression indicates pricing pressure or cost issues.');
            if (finalShare > 25) insights.push('Market share gains show competitive strength.');
            if (finalShare < 15) insights.push('Market share loss to competitors requires strategic review.');
            if (disruptiveLaunched) insights.push('Successful disruptive product launch created a new revenue stream!');
            if (!disruptiveLaunched && history.length >= 3) insights.push('No disruptive innovation launched. Higher R&D allocation to disruptive projects could have opened new markets.');
            if (finalBrand > 70) insights.push('Strong brand equity provides pricing power and customer loyalty.');
            if (finalBrand < 40) insights.push('Low brand equity leaves the company vulnerable to price competition.');

            return {
                tmvi: tmvi,
                totalRevenue: totalRevenue,
                totalProfit: totalProfit,
                avgMargin: Math.round(avgMargin * 10) / 10,
                finalMarketShare: finalShare,
                finalBrandEquity: finalBrand,
                revenueGrowth: Math.round(revenueGrowth),
                disruptiveLaunched: disruptiveLaunched,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.netProfit < 0) return window.mySimulation.t('hint_loss');
            if (results.grossMargin < 30) return window.mySimulation.t('hint_margin');
            if (state.domainState.marketShare < 15) return window.mySimulation.t('hint_share');
            if (state.currentPeriod >= 2 && state.domainState.rdPipelineProgress < 30) return window.mySimulation.t('hint_rd');
            if (results.disruptiveLaunched) return window.mySimulation.t('hint_disruptive_success');
            if (state.domainState.brandEquity > 70 && results.netProfit > 500) return window.mySimulation.t('hint_strong');
            return null;
        }

